INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", "2024/10/31 12:00:00", 2.1, 130011, 1, "2030/01/01 14:59:59", 2, 3001, "ヤマト", -416.5, 100, 0.0, 3001100);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", "2024/10/31 12:00:00", 5.68, 130011, 4, "2030/01/01 14:59:59", 2, 3001, "ヤマト", -416.5, 101, 0.0, 3001101);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", "2024/10/31 12:00:00", 0.0, 130011, 1, "2030/01/01 14:59:59", 1, 3001, "ヤマト", -416.5, 102, 0.0, 3001102);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", "2024/10/31 12:00:00", 0.0, 130211, 1, "2030/01/01 14:59:59", 1, 3002, "フブキ", -416.5, 100, 0.0, 3002100);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", "2024/10/31 12:00:00", 0.0, 130211, 1, "2030/01/01 14:59:59", 1, 3002, "フブキ", -416.5, 101, 0.0, 3002101);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", "2024/10/31 12:00:00", 8.53, 130211, 5, "2030/01/01 14:59:59", 2, 3002, "フブキ", -416.5, 102, 0.0, 3002102);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", "2024/10/31 12:00:00", 5.67, 130211, 7, "2030/01/01 14:59:59", 1, 3002, "フブキ", -416.5, 103, 0.0, 3002103);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", "2024/10/31 12:00:00", 0.0, 130211, 1, "2030/01/01 14:59:59", 1, 3002, "フブキ", -416.5, 104, 0.0, 3002104);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", "2024/10/31 12:00:00", 0.0, 130211, 3, "2030/01/01 14:59:59", 3, 3004, "フブキ", -416.5, 300, 0.0, 3002300);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", "2024/10/31 12:00:00", 0.0, 130211, 7, "2030/01/01 14:59:59", 7, 3005, "フブキ", -416.5, 301, 0.0, 3002400);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", "2024/10/31 12:00:00", 4.4, 130211, 2, "2030/01/01 14:59:59", 1, 3003, "フブキ", -416.5, 200, 0.0, 3003200);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES ("は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", "2024/10/31 12:00:00", 0.0, 130211, 7, "2030/01/01 14:59:59", 7, 3003, "フブキ", -416.5, 201, 0.0, 3003201);
